export type FaqItem = { question: string; answer: string };
export type ContentBlock =
  | { type: "paragraph"; text: string }
  | { type: "subheading"; text: string }
  | { type: "list"; items: string[] }
  | { type: "table"; headers: string[]; rows: string[][]; caption?: string }
  | { type: "quote"; text: string }
  | { type: "keyFacts"; items: { label: string; value: string }[] }
  | { type: "evidenceSlot"; label: string; description: string; caption: string }
  | { type: "evidenceImage"; src: string; alt: string; label: string; caption: string; sourceUrl: string }
  | { type: "pricingTable"; toolKey: string }
  | { type: "internalLink"; href: string; label: string; description?: string }
  | { type: "externalLink"; href: string; label: string; description?: string };
export type ContentSection = { heading: string; paragraphs?: string[]; bullets?: string[]; blocks?: ContentBlock[]; id?: string };
export type PageCard = { title: string; description: string; href: string; label?: string; linkLabel?: string; bestFor?: string; myTake?: string; limitation?: string; chooseIf?: string };
export type ArticleCta = { afterSection?: string; eyebrow: string; heading: string; description: string; toolKey: string; label: string; secondaryHref?: string; secondaryLabel?: string };
export type ReviewDecision = { status: string; basis: string; bestFor: string; mainStrength: string; mainWeakness: string; recommendation: string; toolKey: string; ctaLabel: string };

export type ArticlePage = {
  slug: string; title: string; h1: string; description: string; eyebrow: string; intro: string; verdict: string;
  bestFor: string[]; watchFor: string[]; sections: ContentSection[]; workflow: string[]; faqs: FaqItem[]; related: string[];
  kind: "hub" | "pillar" | "review" | "comparison" | "guide" | "trust" | "legal";
  cards?: PageCard[]; toolKey?: string; toolKeys?: string[]; researchStatus?: ResearchStatus; disclaimer?: string;
  informational?: boolean; verdictLabel?: string; earlyCta?: ArticleCta; midCta?: ArticleCta; finalCta?: ArticleCta;
  myView?: string; showPricingNotice?: boolean;
  reviewDecision?: ReviewDecision; hideProsCons?: boolean; hideDecisionSnapshot?: boolean; hideMyView?: boolean; hideWorkflow?: boolean;
  hideNewsletter?: boolean; operatorViewAfterSection?: string; reviewBasisLabel?: string; hideOperatorView?: boolean; hideQuickVerdict?: boolean;
  hideFaq?: boolean; hideSourceList?: boolean; hideComparisonTable?: boolean; hideFinalCta?: boolean; hideDisclosure?: boolean;
  cardsHeading?: string; reviewDates?: { testConducted: string; pricingChecked: string }; sectionCtas?: ArticleCta[];
  publishedIso?: string; modifiedIso?: string;
  reviewRating?: { ratingValue: number; bestRating: number; worstRating: number; itemName: string; itemUrl: string };
  itemList?: { name: string; url: string; position: number }[];
};

const disclaimer = "Ecommerce research platforms may show modeled or estimated data. Use their signals to build a shortlist, then verify demand, margin, supplier risk and platform policy with current first-party evidence.";
const standardFaqs = (name: string): FaqItem[] => [
  { question: `What is the main use of ${name}?`, answer: `${name} is most useful when it supports a recurring research question such as finding products, reviewing competitors or studying advertising patterns. Start with a defined market and output before choosing a plan.` },
  { question: `Can ${name} guarantee a winning product?`, answer: "No. Software can organize signals and reduce browsing time, but it cannot guarantee demand, margin, creative performance or future sales." },
  { question: "Are third-party sales or revenue figures official?", answer: "Treat them as estimates unless the provider clearly identifies a first-party source and methodology. Cross-check important decisions with platform-native data." },
  { question: `How should I evaluate ${name.replace(/\s+pricing$/i, "")} pricing?`, answer: `Check the current official plan page for markets, seats, history, exports, limits and billing terms. Compare the cost with the number of repeatable decisions the workflow supports.` },
];

type ReviewInput = {
  slug: string; name: string; title: string; description: string; focus: string; audience: string; platforms: string;
  features: string[]; strengths: string[]; limitations: string[]; differentiator: string; related: string[]; toolKey: string; sources: { label: string; href: string }[];
};

function reviewPage(input: ReviewInput): ArticlePage {
  const { name } = input;
  const page: ArticlePage = {
    slug: input.slug, title: input.title, h1: input.title.split(":")[0], description: input.description,
    eyebrow: "Independent software review", intro: `${name} is easiest to judge when the research question is concrete. This review looks at ${input.focus}, then separates the useful signal from the checks that still belong to the operator.`,
    verdict: `${name} deserves a trial for ${input.audience.toLowerCase()} when ${input.differentiator}. I would pause the purchase when the team expects estimates or dashboard breadth to replace margin, supply, policy or creative validation.`,
    bestFor: [input.audience, `Teams researching ${input.platforms}`, "Operators with a defined weekly research question"],
    watchFor: ["Coverage and plan limits can change", ...input.limitations.slice(0, 2)], kind: "review", toolKey: input.toolKey,
    researchStatus: "Feature research and operator workflow evaluation", hideNewsletter: true, showPricingNotice: true, disclaimer,
    sections: [
      { heading: "Quick answer", paragraphs: [`${name} is worth considering when its coverage and workflow match the evidence you need every week. Do not subscribe because a dashboard shows a large opportunity number or because a competitor appears to have a feature you have not defined.`, `My first check would be one known product, one known competitor and one market that matters to the business. If the tool cannot retrieve or explain those examples, a longer trial will rarely repair the gap.`] },
      { heading: `What ${name} does`, paragraphs: [`Public product information positions ${name} around ${input.focus}. In practice, the useful unit is a research brief: a question, a set of comparable records, a dated observation window and a next action.`, `The platform sits in the discovery and comparison part of that process. It does not confirm landed cost, returns, policy eligibility, creative quality or the durability of demand. Keep those checks visible in the operating record.`] },
      { heading: "Features that affect the decision", bullets: input.features, paragraphs: [`The feature list only matters when it changes a decision. Ask whether each capability improves candidate discovery, competitor monitoring, evidence capture or team handoff. A long list with unclear dates and limits is less useful than a smaller set of reproducible records.`, `Before paying, confirm the current official product pages for the markets, channels, historical windows, exports and seats required by your workflow. This review does not turn a changing plan into a permanent promise.`] },
      { heading: "Where it fits in an ecommerce workflow", paragraphs: [`Start with a category or competitor question, set a recent observation window and record the filters used. Build a broad list first, then narrow it using signals that are relevant to the decision. Save the reason each candidate survived and the risk that could disqualify it.`, `${name} should shorten investigation, not remove judgment. Compare its output with platform-native records, supplier quotes and your own unit-economics sheet before inventory, creator or ad commitments.`] },
      { heading: "The practical strengths", bullets: input.strengths, paragraphs: [`The strongest case for ${name} is consistency. A team can ask the same question across multiple candidates and retain a shared trail of what was seen, when it was seen and what still needs verification.`, `That consistency is more valuable than a headline metric. Direction, concentration and change over time can guide the next check even when the underlying number is modeled.`] },
      { heading: "Limitations and evidence gaps", bullets: input.limitations, paragraphs: [`Every third-party dataset has coverage boundaries. Collection methods, country support, category depth and historical availability can differ. Label estimates clearly in internal notes and do not present them as confirmed revenue or sales.`, `A useful stop condition is a missing or implausible known example. If the tool cannot explain the gap, pause the purchase and use an official platform source or a manual research path.`] },
      { heading: "Sources and freshness", paragraphs: ["The links below are the official product or platform references used to frame this evaluation. Product pages, plan terms and coverage can change, so open them again before subscribing."], blocks: input.sources.map((source) => ({ type: "externalLink" as const, href: source.href, label: source.label })) },
      { heading: "Pricing and commitment", paragraphs: [`Pricing, trials and limits can change. Check the current ${name} pricing page before subscribing and compare the plan with the actual number of markets, exports, seats and recurring investigations required.`, `A short commitment is safer until the team has completed several normal workflows. Measure qualified candidates and decisions produced, rather than counting dashboard views.`] },
      { heading: "Who should use it", paragraphs: [`${name} is a reasonable shortlist candidate for ${input.audience.toLowerCase()} who already have a verification process. It can be useful when several people need the same research method or when the team repeatedly investigates ${input.platforms}.`, `Use it with a written trial brief. If the workflow ends in a defensible shortlist and clear follow-up checks, the subscription has a credible operating role.`] },
      { heading: "Who should skip it", paragraphs: [`Skip or postpone the subscription when the business has no defined question, expects automatic product selection or cannot validate estimates. A research tool cannot repair unclear positioning, weak contribution margin or supplier risk.`, `A narrow operator may also get enough value from public ad libraries, platform-native reports and a dated spreadsheet. Pay when the recurring volume justifies the system.`] },
      { heading: "Final verdict", paragraphs: [`${name} is worth testing only against the workflow it is meant to improve. My recommendation is to start with the smallest commitment, verify the current terms, and keep a written record of what the platform did and did not establish.`, disclaimer] },
    ],
    workflow: ["Write the market, question and required output before opening the tool.", "Test one known product and one known competitor.", "Record dates, filters, estimates and missing evidence.", "Verify the shortlist with first-party, supplier and margin checks.", "Choose a paid plan only if the repeated workflow saves meaningful operator time."],
    faqs: standardFaqs(name), related: input.related,
    earlyCta: input.toolKey === "winninghunter" ? { eyebrow: "Decision step", heading: "Check the current WinningHunter destination", description: "Confirm current features and terms before starting a representative research task.", toolKey: input.toolKey, label: "Explore WinningHunter", secondaryHref: "/winninghunter-pricing", secondaryLabel: "See pricing guidance" } : undefined,
    sectionCtas: input.toolKey === "winninghunter" ? undefined : [{ afterSection: "The question to settle before subscribing", eyebrow: "Related workflow", heading: "Check WinningHunter's Ad-to-Store Path", description: `If ${name} leaves you needing to connect advertising activity with a Shopify store or product, compare WinningHunter against the same brief before adding another subscription.`, toolKey: "winninghunter", label: "Explore WinningHunter", secondaryHref: "/winninghunter-review", secondaryLabel: "Read the review" }],
  };
  page.sections.splice(1, 0, { heading: "The operator check", paragraphs: [`For ${name}, the first test is whether ${input.differentiator} creates a decision another operator can explain. A feature only earns value when it changes the shortlist, the monitoring plan or the next validation step.`, `Use a written brief for ${input.audience.toLowerCase()} and keep ${input.platforms} evidence separate from estimates. That makes the subscription easier to review and easier to cancel when the workflow changes.`] });
  page.disclaimer = `${disclaimer} In this ${name} review, treat activity and trend figures as directional until the current source and operating evidence agree.`;
  return page;
}

function comparisonPage(slug: string, title: string, description: string, left: string, right: string, focus: string, related: string[]): ArticlePage {
  const leftKey = left.toLowerCase().replaceAll(" ", "");
  const rightKey = right.toLowerCase().replaceAll(" ", "");
  const pair = `${left} versus ${right}`;
  const leftPricing = pricingByTool[leftKey as keyof typeof pricingByTool];
  const rightPricing = pricingByTool[rightKey as keyof typeof pricingByTool];
  const leftPriceSummary = getPricingSummary(leftKey);
  const rightPriceSummary = getPricingSummary(rightKey);
  const pricingDecisionParagraph = right === "Kalodata"
    ? "For a TikTok Shop comparison, include the markets, creator or shop history and export access that the brief needs. A lower displayed price is not a saving if the required entities are unavailable."
    : right === "PipiAds"
      ? "For an ad-library comparison, include search credits, detail views, tracker limits and the channels that matter to the creative brief. Count completed briefs, not saved ads, when judging the subscription."
      : "For a store-research comparison, include store limits, history, exports and seats in the cost model. A cheaper plan is not cheaper if the operator must rebuild the same evidence manually.";
  const pricingTermsParagraph = right === "Kalodata"
    ? "Before a TikTok Shop commitment, verify the billing cycle, trial access, cancellation path and any annual offer on the live plan page."
    : right === "PipiAds"
      ? "Before an ad-library commitment, verify the billing cycle, trial access, cancellation path and any annual offer on the live plan page."
      : "Before a store-research commitment, verify the billing cycle, trial access, cancellation path and any annual offer on the live plan page.";
  const pricingSnapshotParagraph = right === "Kalodata"
    ? `The ${left} amount is visible in the current public snapshot; Kalodata's public amount was not confirmed. I recorded both statuses on ${leftPricing?.lastChecked || "the review date"} so the comparison does not turn an unavailable plan into a guessed number.`
    : right === "PipiAds"
      ? `The public snapshot shows monthly amounts for both ${left} and ${right}. I recorded the plan names and check date on ${leftPricing?.lastChecked || "the review date"}; confirm credits, access and annual terms before treating the difference as total cost.`
      : `The ${left} amount is visible in the current public snapshot; ShopHunter's public amount was not confirmed. I recorded both statuses on ${leftPricing?.lastChecked || "the review date"} and link the official destinations below for a fresh check.`;
  const pricingTableCaption = right === "Kalodata"
    ? "Amounts are comparison text; use the linked official sources to verify Kalodata access and current WinningHunter terms."
    : right === "PipiAds"
      ? "Amounts are comparison text; verify credits, seats, billing cycle and current annual terms on both official destinations."
      : "Amounts are comparison text; verify the current ShopHunter plan destination before comparing total cost.";
  const entityBullet = right === "Kalodata" ? "Products, shops, creators and content entities" : right === "PipiAds" ? "Advertisers, creatives and product entities" : "Stores, products, offers and competitor entities";
  const page: ArticlePage = {
    slug, title, h1: title.split(":")[0], description, eyebrow: "Head-to-head comparison",
    intro: `The hard part of choosing between ${left} and ${right} is that similar dashboards can answer different questions. I recommend comparing them against ${focus}. Start with the same known entities and test the evidence each one produces before paying.`,
    verdict: `Choose ${left} when its focused workflow matches the primary question. Choose ${right} when its coverage or operating model answers a different question more completely. A feature count alone is not a tie-breaker.`,
    bestFor: [`Teams comparing ${left} and ${right}`, `Operators testing ${left} and ${right} with the same market and entities`, "Buyers who can verify current pricing"],
    watchFor: ["Coverage varies by market and plan", "Modeled metrics need independent verification", "A comparison cannot prove live-account performance"], kind: "comparison", toolKeys: [leftKey, rightKey], related, disclaimer,
    earlyCta: leftKey === "winninghunter" ? { eyebrow: "Primary recommendation", heading: "Start with WinningHunter", description: "Use the focused ad-to-product and Shopify research path first, then compare the second tool only when its entity model solves a different recurring question.", toolKey: "winninghunter", label: "Explore WinningHunter", secondaryHref: "/winninghunter-pricing", secondaryLabel: "Review pricing checks" } : undefined,
    sections: [
      { heading: "Quick comparison", paragraphs: [`${left} and ${right} can appear interchangeable when both show products, competitors or ads. The real difference is the path from a question to evidence: which entities are covered, how recent the records are, what the operator can export and which checks remain outside the tool.`, `Run the same task in both products. Use a known product, a known competitor and a market that matters to you. Record missing records and unexplained estimates alongside the successful finds.`], blocks: [{ type: "table", headers: ["Decision area", left, right], rows: [["Primary workflow", left === "WinningHunter" ? "Product and ad research connected to stores" : "Focused marketplace or competitor research", right === "Kalodata" ? "TikTok Shop product, shop and creator signals" : "Alternative workflow with different coverage"], ["Best first test", "Known product and ad or store path", "Known entity and recent market record"], ["Pricing", leftPriceSummary, rightPriceSummary], ["Main caution", "Confirm current plan coverage", "Treat modeled metrics as estimates"]], caption: "Use the same entities, date range and price basis before choosing a subscription." }] },
      { heading: "Who each tool is for", paragraphs: [`${left} fits operators whose recurring question is ${focus}. Its advantage is useful only when the team can connect the output to a next action such as monitoring a competitor, checking a creative pattern or validating a product candidate.`, `${right} is a better fit when the required evidence sits in a different channel, market or entity model. Do not force a marketplace question into an advertising workflow, or an advertising question into a marketplace dashboard.`] },
      { heading: "Feature and coverage checks", paragraphs: [`For ${left} versus ${right}, compare platform coverage, data freshness, filters, history, exports and shared access. Ask each vendor how a record is collected and how a modeled number should be interpreted.`, `The correct winner can change by country, category and team size. In this ${pair} decision, a tool that is stronger for one market may be a poor choice for another, so keep the recommendation conditional and recheck the live plan page.`], bullets: [`${left} and ${right} platform and country coverage`, entityBullet, "Date ranges and update cadence", "Exports, seats and collaboration", "Pricing, trial and cancellation terms"] },
      { heading: "Price comparison", paragraphs: [pricingSnapshotParagraph, pricingDecisionParagraph, pricingTermsParagraph], blocks: [{ type: "table", headers: ["Price check", left, right], rows: [["Published monthly plans", leftPriceSummary, rightPriceSummary], ["Price evidence", leftPricing?.plans.length ? "Public plan amounts visible" : "Public amount not confirmed", rightPricing?.plans.length ? "Public plan amounts visible" : "Public amount not confirmed"], ["Checked", leftPricing?.lastChecked || "Not recorded", rightPricing?.lastChecked || "Not recorded"]], caption: pricingTableCaption }] },
      { heading: `Choose ${left} if...`, paragraphs: [`Choose ${left} if the team values a direct path from ${focus} to a short, explainable research brief. Confirm the records using a normal workflow before making an annual commitment.`, `${left} earns the decision in this ${pair} when it produces a measurable reduction in repeated investigation. If it only produces attractive screenshots, keep the research manual.`] },
      { heading: `Choose ${right} if...`, paragraphs: [`Choose ${right} if its entity model, channel coverage or market depth matches the question better. Test known records first and document which fields are truly available in the plan you can buy.`, `${right} earns the decision when it fits the team's existing process. A different interface is useful only when it changes the quality or speed of the decision.`] },
      { heading: "Final recommendation", paragraphs: [`Run a matched ${pair} brief before choosing. Keep both outputs, compare what each proves and list what neither proves. Then select the smallest plan that supports the recurring workflow and keep first-party verification in the same operating record. Start with one documented brief and review the result with the operator who will own the subscription. Ask what changed in the decision, which records were missing, and whether the remaining manual checks are acceptable for the next month of work.`, `${disclaimer} This ${pair} recommendation stays conditional until the matched brief confirms it.`] },
    ],
    workflow: [`Define one ${pair} question and two known test entities.`, `Run the same market and date range in ${left} and ${right}.`, `Compare ${left} and ${right} on evidence, missing records, exports and follow-up work.`, `Check the current ${left} and ${right} plan terms.`, `Choose the product that improves this ${pair} decision.`],
    faqs: standardFaqs(`${left} versus ${right}`),
  };
  page.disclaimer = `${disclaimer} In this ${pair} comparison, treat the difference as directional until a matched workflow confirms it.`;
  return page;
}

